const ENTRY_INTENT_INDEX=Object.freeze({
  opening:Object.freeze(['recognize_arrival','warm_welcome','calm_presence','ready_to_listen','welcome_back','gentle_reconnect','practical_welcome','quiet_attention']),
  stance:Object.freeze(['warm_and_direct','calm_and_patient','concise_and_clear','supportive_without_assumption','context_aware']),
  context:Object.freeze(['invite_issue','invite_expected_result','invite_confusing_step','invite_priority','offer_open_start','offer_status_or_explanation','resume_open_topic','ask_what_changed','resume_saved_context','invite_new_evidence','offer_status_or_next_step','acknowledge_unfinished_question']),
  prompt:Object.freeze(['open_question','expected_vs_actual','first_useful_detail','preferred_starting_point','current_priority','next_observable_change','status_explanation_or_problem','continue_or_new_topic']),
})
function entryPick(locale,key,value=''){
  const rows=ENTRY_NATIVE[locale]?.[key]||ENTRY_NATIVE.en[key]
  const intents=ENTRY_INTENT_INDEX[key]||[]
  const found=intents.indexOf(String(value||''))
  const index=found>=0?found:mixedHash32(`${locale}:${key}:${value}`)
  return rows[index%rows.length]
}

function arr(value){return Array.isArray(value)?value:[]}
function pick(rows=[],seed=''){const values=arr(rows).filter(Boolean);if(!values.length)return'';return values[Number.parseInt(ql7StableHash(seed).slice(0,8),16)%values.length]}
function mixedHash32(value=''){let x=Number.parseInt(ql7StableHash(value),16)>>>0;x^=x>>>16;x=Math.imul(x,0x85ebca6b)>>>0;x^=x>>>13;x=Math.imul(x,0xc2b2ae35)>>>0;x^=x>>>16;return x>>>0}
function mixedPick(rows=[],seed=''){const values=arr(rows).filter(Boolean);if(!values.length)return'';return values[mixedHash32(seed)%values.length]}
function atom(lex,key,seed){return pick(lex[key],`${seed}:${key}`)}
function mixedAtom(lex,key,seed){return mixedPick(lex[key],`${seed}:${key}`)}
function variantAtom(lex,key,variant=0,radixOffset=0){const values=arr(lex[key]).filter(Boolean);if(!values.length)return'';const index=Math.floor(Math.max(0,Number(variant)||0)/Math.max(1,Number(radixOffset)||1))%values.length;return values[index]}
function clean(...parts){return parts.map(ql7Str).filter(Boolean).join(' ').replace(/\s+([,.;:!?؟。])/gu,'$1').replace(/\s+/gu,' ').trim()}
function stripTerminal(value=''){return ql7Str(value).replace(/[.!?。！？؟]+$/u,'')}
function terminal(profile,kind='statement'){if(kind==='question'){if(profile.locale==='ar')return'؟';if(profile.locale==='zh')return'？';return'?'}if(profile.locale==='zh')return'。';return'.'}
function sentence(profile,kind,...parts){const body=stripTerminal(clean(...parts));return body?`${body}${terminal(profile,kind)}`:''}
function variables(v={}){return{topic:ql7Str(v.topic),detail:ql7Str(v.detail),secondaryDetail:ql7Str(v.secondaryDetail),variant:Math.max(0,Math.trunc(Number(v.variant)||0)),focus:ql7Str(v.focus),contrast:ql7Str(v.contrast),tone:ql7Str(v.tone),form:ql7Str(v.form),entryMode:ql7Str(v.entryMode),openingIntentId:ql7Str(v.openingIntentId),stanceIntentId:ql7Str(v.stanceIntentId),contextIntentId:ql7Str(v.contextIntentId),promptIntentId:ql7Str(v.promptIntentId),rhetoricalShapeId:ql7Str(v.rhetoricalShapeId),mechanismId:ql7Str(v.mechanismId),setupConceptId:ql7Str(v.setupConceptId),pivotConceptId:ql7Str(v.pivotConceptId),closureConceptId:ql7Str(v.closureConceptId)}}
const VERIFIED_FRAMES=Object.freeze({
 en:Object.freeze(['Verified data for {topic} came from an approved source','The current {topic} details were confirmed by an authorized source check']),
 ru:Object.freeze(['Проверенные данные по разделу «{topic}» получены из разрешённого источника','Сведения по разделу «{topic}» подтверждены актуальной проверкой источника']),
 uk:Object.freeze(['Перевірені дані щодо розділу «{topic}» отримано з дозволеного джерела','Відомості щодо розділу «{topic}» підтверджено актуальною перевіркою джерела']),
 es:Object.freeze(['Los datos verificados de {topic} proceden de una fuente autorizada','La información actual de {topic} fue confirmada mediante una comprobación autorizada']),
 tr:Object.freeze(['{topic} için doğrulanan veriler yetkili bir kaynaktan alındı','Güncel {topic} bilgileri yetkili kaynak kontrolüyle doğrulandı']),
 ar:Object.freeze(['تم الحصول على البيانات المتحقق منها بشأن {topic} من مصدر مصرح به','تم تأكيد معلومات {topic} الحالية من خلال فحص مصدر مصرح به']),
 zh:Object.freeze(['{topic} 的已验证数据来自获准来源','当前 {topic} 信息已通过授权来源检查确认']),
 he:Object.freeze(['הנתונים המאומתים עבור {topic} התקבלו ממקור מורשה','המידע העדכני על {topic} אומת בבדיקת מקור מורשה']),
})
function verifiedSentence(profile,topic,variant=0){const rows=VERIFIED_FRAMES[profile.locale]||VERIFIED_FRAMES.en;const frame=rows[Math.max(0,Number(variant)||0)%rows.length];const fallback=profile.locale==='ru'?'запрошенному разделу':'the requested topic';return sentence(profile,'statement',frame.replace('{topic}',topic||fallback))}

const PRODUCT_TOPIC_RE=/(?:QCoin|BattleCoin|MetaMarket|Gameverse|MetaStudio|CryptoRadar|Quantum\s+Wallet|AI\s+Box|VIP(?:\s+Plus)?|NFT|BTC|ETH|USDT)/iu
function bankAtom(profile,family,seed='',offset=0){
  const rows=Array.isArray(profile?.banks?.[family])?profile.banks[family]:[]
  if(!rows.length)return''
  const index=(mixedHash32(`${profile.locale}:${family}:${seed}`)+Math.max(0,Number(offset)||0))%rows.length
  return ql7Str(rows[index]?.lexicalChoices?.[0])
}
function nativeTopic(profile,value='',seed=''){
  const raw=ql7Str(value)
  if(raw&&PRODUCT_TOPIC_RE.test(raw))return raw
  return bankAtom(profile,'lexicalAliasBank',`${seed}:topic`)
}
function composeProfileNative(profile,operation,v,seed=''){
  const x=variables(v),b=(family,suffix='',offset=0)=>bankAtom(profile,family,`${seed}:${suffix}`,offset)
  const topic=nativeTopic(profile,x.topic,seed)
  const statement=(...parts)=>sentence(profile,'statement',...parts)
  const question=(...parts)=>sentence(profile,'question',...parts)
  switch(operation){
    case'greeting':return statement(b('pragmaticsBank','greeting'),b('lexicalAliasBank','greeting-alias'))
    case'entryGreeting':return clean(statement(b('explanationStrategyBank','entry-explain')),question(b('clarificationStrategyBank','entry-clarify')))
    case'invite':return question(b('clarificationStrategyBank','invite'),b('explanationStrategyBank','invite-explain'))
    case'thanks':return statement(b('gratitudeBank','thanks'))
    case'farewell':return statement(b('pragmaticsBank','farewell'),b('gratitudeBank','farewell-gratitude'))
    case'wellbeing':return question(b('emotionAcknowledgementBank','wellbeing'),b('clarificationStrategyBank','wellbeing-question'))
    case'noise':return statement(b('emptyNoiseRecoveryBank','noise'),b('clarificationStrategyBank','noise-clarify'))
    case'clarify':return question(b('clarificationStrategyBank','clarify'),topic)
    case'abstain':return statement(b('emptyNoiseRecoveryBank','abstain'),b('explanationStrategyBank','abstain-explain'))
    case'emotion':return question(b('emotionAcknowledgementBank','emotion'),b('clarificationStrategyBank','emotion-question'))
    case'socialBoundary':return question(b('pragmaticsBank','social'),b('clarificationStrategyBank','social-question'))
    case'identity':return statement(b('lexicalAliasBank','identity'),b('explanationStrategyBank','identity-explain'))
    case'reportedSpeech':return question(b('quotationBank','reported'),b('clarificationStrategyBank','reported-question'))
    case'targetClarify':return question(b('clarificationStrategyBank','target'),b('quotationBank','target-quote'))
    case'denialRepair':return statement(b('negationBank','denial'),b('pragmaticsBank','denial-pragmatics'))
    case'boundary':return statement(b('pragmaticsBank','boundary'),b('explanationStrategyBank','boundary-explain'))
    case'crisis':return statement(b('emotionAcknowledgementBank','crisis'),b('instructionStrategyBank','crisis-step'))
    case'threat':return statement(b('incidentStrategyBank','threat'),b('instructionStrategyBank','threat-step'))
    case'business':return question(b('incidentStrategyBank','business'),b('clarificationStrategyBank','business-question'))
    case'contact':return statement(b('contactAcknowledgementBank','contact'),b('pragmaticsBank','contact-pragmatics'))
    case'handoff':return statement(b('contactAcknowledgementBank','handoff'),b('instructionStrategyBank','handoff-step'))
    case'noNewFact':return question(b('emptyNoiseRecoveryBank','no-new-fact'),b('clarificationStrategyBank','no-new-fact-question'))
    case'incident':return question(b('incidentStrategyBank','incident'),b('clarificationStrategyBank','incident-question'))
    case'unavailable':{const e=getQl7SupportSourceEvidenceLexicon(profile.locale);return statement(e.sourceUnavailable,topic,e.noGuess)}
    case'verified':{const e=getQl7SupportSourceEvidenceLexicon(profile.locale);return statement(e.verified,topic,e.approvedSource)}
    case'empty':return statement(b('badgeSemanticBank','empty',0),b('titleSemanticBank','empty-title'),topic)
    case'planned':return statement(b('titleSemanticBank','planned'),topic,b('explanationStrategyBank','planned-explain'))
    case'knowledge':return statement(b('explanationStrategyBank','knowledge'),topic)
    case'howTo':return statement(b('instructionStrategyBank','howto'),topic,b('ctaSemanticBank','howto-cta'))
    case'smallTalk':return question(b('emotionAcknowledgementBank','smalltalk'),b('clarificationStrategyBank','smalltalk-question'))
    case'aiQuota':return statement(b('explanationStrategyBank','aiquota'),b('ctaSemanticBank','aiquota-cta'),topic)
    case'aiDisclaimer':return statement(b('explanationStrategyBank','aidisclaimer'),b('pragmaticsBank','aidisclaimer-pragmatics'))
    case'humor':{
      const lexical=buildQl7SupportHumorLexicalPlan({locale:profile.locale,mechanismId:x.mechanismId,setupConceptId:x.setupConceptId,pivotConceptId:x.pivotConceptId,closureConceptId:x.closureConceptId})
      if(lexical?.mechanism&&lexical?.setup&&lexical?.pivot&&lexical?.closure)return clean(statement(lexical.setup,lexical.mechanism),statement(lexical.pivot,lexical.closure))
      return statement(b('humorMechanismBank','humor'),topic)
    }
    case'topicRecall':return statement(b('discourseRelationBank','recall'),topic,b('clarificationStrategyBank','recall-question'))
    case'noveltyFallback':return question(b('clarificationStrategyBank',`novelty:${x.variant}`),topic,b('explanationStrategyBank',`novelty-explain:${x.variant}`))
    default:throw Object.assign(new Error(`ql7_compositional_operation_unsupported:${operation}`),{code:'ql7_compositional_operation_unsupported'})
  }
}

function compose(locale,operation,v,seed){
  const profile=getQl7SupportLocaleProfile(locale)
  const lex=L[profile.locale]
  if(!lex)return composeProfileNative(profile,operation,v,seed)
  const x=variables(v),a=(k,s='')=>atom(lex,k,`${seed}:${s}`),m=(k,s='')=>mixedAtom(lex,k,`${seed}:${s}`)
  switch(operation){
    case'greeting':return sentence(profile,'statement',a('hello'))
    case'entryGreeting':{
      const localeId=profile.locale
      const opening=entryPick(localeId,'opening',x.openingIntentId||String(x.variant))
      const context=entryPick(localeId,'context',x.contextIntentId||String(x.variant))
      const stance=entryPick(localeId,'stance',x.stanceIntentId||String(x.variant))
      const prompt=entryPick(localeId,'prompt',x.promptIntentId||String(x.variant))
      const openingSentence=sentence(profile,'statement',opening)
      const contextQuestion=sentence(profile,'question',context)
      const stanceSentence=sentence(profile,'statement',stance)
      const promptQuestion=sentence(profile,'question',prompt)
      const topicRecall=x.entryMode==='continue'&&x.topic?sentence(profile,'statement',variantAtom(lex,'openWas',x.variant,1),x.topic,',',variantAtom(lex,'resume',x.variant,2)):''
      const shape=x.rhetoricalShapeId||'opening_then_prompt'
      if(topicRecall){
        if(shape==='context_opening_prompt')return clean(topicRecall,openingSentence,stanceSentence,promptQuestion)
        if(shape==='opening_prompt_context')return clean(openingSentence,promptQuestion,topicRecall,stanceSentence)
        if(shape==='opening_context_prompt')return clean(openingSentence,topicRecall,stanceSentence,promptQuestion)
        return clean(openingSentence,stanceSentence,topicRecall,promptQuestion)
      }
      if(shape==='context_opening_prompt')return clean(stanceSentence,openingSentence,contextQuestion,promptQuestion)
      if(shape==='opening_prompt_context')return clean(openingSentence,promptQuestion,contextQuestion,stanceSentence)
      if(shape==='opening_context_prompt')return clean(openingSentence,stanceSentence,contextQuestion,promptQuestion)
      return clean(openingSentence,contextQuestion,stanceSentence,promptQuestion)
    }
    case'invite':return sentence(profile,'question',a('ask'),a('want'),a('first'))
    case'thanks':return sentence(profile,'statement',a('welcome'))
    case'farewell':return sentence(profile,'statement',a('care'),a('and'),a('later'))
    case'wellbeing':return sentence(profile,'question',a('well'),a('and'),a('day'))
    case'noise':return sentence(profile,'statement',a('fragment'),a('unclear'),a('then'),a('explain'))
    case'clarify':return x.topic?sentence(profile,'question',a('mean'),x.topic,x.detail?':':'',x.detail):sentence(profile,'question',a('ask'),a('want'))
    case'abstain':return sentence(profile,'statement',a('sensitive'),a('therefore')||a('then'),a('noOpen'))
    case'emotion':return clean(sentence(profile,'statement',a('sorry')),sentence(profile,'question',a('hardest')))
    case'socialBoundary':return sentence(profile,'question',a('talk'),a('and'),a('choose'))
    case'identity':return sentence(profile,'statement',a('identity'),a('purpose'))
    case'reportedSpeech':return sentence(profile,'question',a('reported'),a('notMe'),a('and'),a('whatDo'))
    case'targetClarify':return sentence(profile,'question',a('targetWrong'),a('directed'),a('other'))
    case'denialRepair':return sentence(profile,'statement',a('apology'),a('and'),a('without'))
    case'boundary':return x.topic?sentence(profile,'question',a('help'),a('however'),a('noInsult'),a('then'),a('ask'),a('want'),a('about'),x.topic,a('first')):sentence(profile,'statement',a('help'),a('however'),a('noInsult'))
    case'crisis':return clean(sentence(profile,'statement',a('safety')),sentence(profile,'statement',a('emergency'),a('trusted')))
    case'threat':return sentence(profile,'statement',a('threat'),a('pause'),a('and'),a('review'))
    case'business':return sentence(profile,'statement',a('describe'),a('goal'),',',a('context'),a('and'),a('timeframe'))
    case'contact':return sentence(profile,'statement',a('contact'),a('consent'),a('dm'))
    case'handoff':return sentence(profile,'statement',a('prepared'),a('however'),a('receipt'))
    case'noNewFact':return sentence(profile,'statement',variantAtom(lex,'repeat',x.variant,1),variantAtom(lex,'then',x.variant,2),variantAtom(lex,'change',x.variant,4))
    case'incident':return sentence(profile,'statement',a('incident'),a('then'),a('evidence'),a('detail'))
    case'unavailable':return sentence(profile,'statement',a('cannot'),x.topic,a('source'),a('guess'))
    case'verified':return verifiedSentence(profile,x.topic,x.variant)
    case'empty':return sentence(profile,'statement',a('checked'),a('none'),x.topic?clean(a('about'),x.topic):'')
    case'planned':return sentence(profile,'statement',x.topic,a('planned'),a('and'),a('released'))
    case'knowledge':return sentence(profile,'statement',a('answer'),x.topic,a('sourced'))
    case'howTo':return sentence(profile,'statement',a('open'),x.topic,',',a('relevant'),a('then'),a('status'))
    case'smallTalk':return sentence(profile,'question',a('brief'),a('and'),a('useful'))
    case'aiQuota':return sentence(profile,'statement',a('quota'),a('calculation'),a('however'),a('vip'))
    case'aiDisclaimer':return sentence(profile,'statement',m('educational'),m('advice'),m('profit'))
    case'humor':{
      // Native-core deterministic fallback stays inside the single compositional owner.
      // Do not splice unrelated semantic banks into a pseudo-joke: that produced
      // machine-like text such as "support / reason / thank you" before neural
      // generation is promoted. The trained generator remains the primary owner;
      // this branch is only the fail-closed bootstrap realization.
      const cue=a('humorCue','humor-cue')
      const intro=a('humorA','humor-intro')
      const subject=a('humorSubject','humor-subject')
      const move=a('humorB','humor-move')
      const close=a('humorC','humor-close')
      return sentence(profile,'statement',cue,':',subject,move,close)
    }
    case'noveltyFallback':{
      const v=x.variant
      const primary=x.detail||a('detail',`fallback-primary:${v}`)
      const secondary=x.secondaryDetail||a('status',`fallback-secondary:${v}`)
      const topic=x.topic||a('fragment',`fallback-topic:${v}`)
      const shapes=[
        ()=>sentence(profile,'question',a('mean',`nf0:${v}`),topic,primary,a('or',`nf0o:${v}`),secondary),
        ()=>sentence(profile,'question',a('ask',`nf1:${v}`),primary,a('about',`nf1a:${v}`),topic,a('or',`nf1o:${v}`),secondary,a('first',`nf1f:${v}`)),
        ()=>sentence(profile,'question',a('useful',`nf2:${v}`),a('about',`nf2a:${v}`),topic,primary,a('or',`nf2o:${v}`),secondary),
        ()=>sentence(profile,'question',a('whatDo',`nf3:${v}`),a('about',`nf3a:${v}`),topic,primary,a('or',`nf3o:${v}`),secondary),
        ()=>sentence(profile,'question',a('describe',`nf4:${v}`),a('goal',`nf4g:${v}`),a('about',`nf4a:${v}`),topic,a('and',`nf4n:${v}`),primary),
        ()=>sentence(profile,'question',a('ask',`nf5:${v}`),a('want',`nf5w:${v}`),a('about',`nf5a:${v}`),topic,secondary,a('or',`nf5o:${v}`),primary),
        ()=>sentence(profile,'question',a('mean',`nf6:${v}`),primary,a('about',`nf6a:${v}`),topic,a('or',`nf6o:${v}`),a('whatDo',`nf6d:${v}`)),
        ()=>sentence(profile,'question',a('useful',`nf7:${v}`),primary,secondary,a('or',`nf7o:${v}`),a('context',`nf7c:${v}`)),
        ()=>sentence(profile,'question',a('describe',`nf8:${v}`),primary,a('about',`nf8a:${v}`),topic,a('or',`nf8o:${v}`),a('timeframe',`nf8t:${v}`)),
        ()=>sentence(profile,'question',a('ask',`nf9:${v}`),a('first',`nf9f:${v}`),a('about',`nf9a:${v}`),topic,primary,a('and',`nf9n:${v}`),secondary),
        ()=>sentence(profile,'question',a('mean',`nf10:${v}`),topic,a('however',`nf10h:${v}`),primary,a('or',`nf10o:${v}`),secondary),
        ()=>sentence(profile,'question',a('whatDo',`nf11:${v}`),a('then',`nf11t:${v}`),a('ask',`nf11a:${v}`),primary,a('about',`nf11b:${v}`),topic),
      ]
      return shapes[v%shapes.length]()
    }
    case'topicRecall':return sentence(profile,'statement',a('openWas'),x.topic,',',a('resume'))
    default:throw Object.assign(new Error(`ql7_compositional_operation_unsupported:${operation}`),{code:'ql7_compositional_operation_unsupported'})
  }
}

export function realizeQl7SupportCompositionalSurface(locale='en',operation='',variables={},seed=''){
  const profile=getQl7SupportLocaleProfile(locale)
  const text=compose(profile.locale,operation,variables,seed)
  const body={schema:'ql7.support.compositional-realization-receipt',schemaVersion:QL7_SUPPORT_COMPOSITIONAL_GRAMMAR_VERSION,ownerId:QL7_SUPPORT_COMPOSITIONAL_GRAMMAR_OWNER_ID,locale:profile.locale,operation,variablesHash:ql7StableHash(JSON.stringify(variables)),seedHash:ql7StableHash(seed),textHash:ql7StableHash(text)}
  const receiptHash=ql7StableHash(JSON.stringify(body))
  return Object.freeze({text,entryId:`${profile.locale}.composition.${operation}`,contentHash:receiptHash,receipt:Object.freeze({...body,receiptId:`composition:${receiptHash}`,receiptHash})})
}

export function auditQl7SupportCompositionalGrammar(){
  const failures=[]
  const variables={topic:'QCoin',detail:'',secondaryDetail:'',variant:0,entryMode:'new'}
  for(const locale of QL7_SUPPORT_PROFILE_LOCALES){
    const profile=getQl7SupportLocaleProfile(locale)
    const authored=L[locale]
    if(authored){
      if(!Array.isArray(authored.humorCue)||authored.humorCue.length<2)failures.push(`missing_humor_cue:${locale}`)
      if(!Array.isArray(authored.humorSubject)||authored.humorSubject.length<2)failures.push(`missing_humor_subject:${locale}`)
      for(const [key,values] of Object.entries(authored))for(const value of values){
        if(['q','dot'].includes(key))continue
        if(!ql7Str(value))failures.push(`blank:${locale}:${key}`)
        if(/[.!?。！？؟]$/u.test(value))failures.push(`ready_sentence_terminal:${locale}:${key}`)
        const words=(ql7Str(value).match(/[\p{L}\p{N}]+/gu)||[]).length
        if(words>16)failures.push(`atom_too_long:${locale}:${key}:${words}`)
      }
    }else{
      for(const family of ['lexicalAliasBank','pragmaticsBank','clarificationStrategyBank','explanationStrategyBank','instructionStrategyBank','incidentStrategyBank','emotionAcknowledgementBank','gratitudeBank','emptyNoiseRecoveryBank','contactAcknowledgementBank','titleSemanticBank','badgeSemanticBank','ctaSemanticBank']){
        if(!Array.isArray(profile?.banks?.[family])||!profile.banks[family].length)failures.push(`missing_profile_bank:${locale}:${family}`)
      }
    }
    for(const operation of QL7_SUPPORT_REQUIRED_COMPOSITIONAL_OPERATIONS){
      try{const text=compose(locale,operation,variables,`audit:${locale}:${operation}`);if(!ql7Str(text))failures.push(`empty_realization:${locale}:${operation}`)}catch(error){failures.push(`realization_error:${locale}:${operation}:${String(error?.code||error?.message||error)}`)}
    }
  }
  return Object.freeze({version:QL7_SUPPORT_COMPOSITIONAL_GRAMMAR_VERSION,nativeLocaleCount:QL7_SUPPORT_PROFILE_LOCALES.length,authoredAtomLocaleCount:Object.keys(L).length,profileDerivedLocaleCount:QL7_SUPPORT_PROFILE_LOCALES.length-Object.keys(L).length,operationCount:QL7_SUPPORT_REQUIRED_COMPOSITIONAL_OPERATIONS.length,finalSentenceRows:0,failures:Object.freeze(failures),ok:failures.length===0})
}

